import unittest
from candidate import median


class TestMedian(unittest.TestCase):
    def test_median_odd_length_single_element(self):
        self.assertEqual(median([5]), 5)

    def test_median_odd_length_three_elements(self):
        self.assertEqual(median([3, 1, 2]), 2)

    def test_median_odd_length_five_elements(self):
        self.assertEqual(median([3, 1, 2, 4, 5]), 3)

    def test_median_even_length_two_elements(self):
        self.assertEqual(median([1, 2]), 1.5)

    def test_median_even_length_four_elements(self):
        self.assertAlmostEqual(median([4, 1, 3, 2]), 2.5)

    def test_median_even_length_six_elements(self):
        self.assertAlmostEqual(median([-10, 4, 6, 1000, 10, 20]), 15.0)

    def test_median_unsorted_input(self):
        self.assertEqual(median([5, 3, 1, 4, 2]), 3)

    def test_median_negative_numbers_odd(self):
        self.assertEqual(median([-5, -1, -3]), -3)

    def test_median_negative_numbers_even(self):
        self.assertAlmostEqual(median([-5, -1]), -3.0)

    def test_median_mixed_positive_negative(self):
        self.assertEqual(median([10, -10, 0]), 0)

    def test_median_mixed_positive_negative_even(self):
        self.assertAlmostEqual(median([10, -10, 20, -20]), 0.0)

    def test_median_floats_odd(self):
        self.assertAlmostEqual(median([1.1, 2.2, 3.3]), 2.2)

    def test_median_floats_even(self):
        self.assertAlmostEqual(median([1.1, 2.2, 3.3, 4.4]), 2.75)

    def test_median_all_same_elements_odd(self):
        self.assertEqual(median([7, 7, 7, 7, 7]), 7)

    def test_median_all_same_elements_even(self):
        self.assertAlmostEqual(median([7, 7, 7, 7]), 7.0)

    def test_median_duplicates_odd(self):
        self.assertEqual(median([1, 1, 2, 3, 3]), 2)

    def test_median_duplicates_even(self):
        self.assertAlmostEqual(median([1, 1, 2, 2]), 1.5)

    def test_median_large_numbers(self):
        self.assertEqual(median([1000000, 2000000, 3000000]), 2000000)

    def test_median_even_returns_float(self):
        result = median([1, 2])
        self.assertIsInstance(result, float)

    def test_median_odd_returns_same_type(self):
        result = median([1, 2, 3])
        self.assertIsInstance(result, int)

    def test_median_empty_list_raises(self):
        with self.assertRaises(Exception):
            median([])

    def test_median_none_raises(self):
        with self.assertRaises(TypeError):
            median(None)

    def test_median_string_input_raises(self):
        with self.assertRaises(Exception):
            median("abc")

    def test_median_integer_input_raises(self):
        with self.assertRaises(Exception):
            median(5)

    def test_median_list_of_strings_raises(self):
        with self.assertRaises(Exception):
            median(['a', 'b', 'c'])

    def test_median_already_sorted(self):
        self.assertEqual(median([1, 2, 3, 4, 5]), 3)

    def test_median_reverse_sorted(self):
        self.assertEqual(median([5, 4, 3, 2, 1]), 3)

    def test_median_zero_values(self):
        self.assertEqual(median([0, 0, 0]), 0)

    def test_median_single_negative(self):
        self.assertEqual(median([-42]), -42)

    def test_median_single_float(self):
        self.assertEqual(median([3.14]), 3.14)

    def test_median_two_elements_reversed(self):
        self.assertEqual(median([2, 1]), 1.5)

    def test_median_does_not_modify_original_list(self):
        original = [3, 1, 2]
        original_copy = original[:]
        median(original)
        self.assertEqual(original, original_copy)

    def test_median_even_result_is_float_type(self):
        self.assertIsInstance(median([1, 3]), float)

    def test_median_large_even_list(self):
        data = list(range(1, 101))
        self.assertAlmostEqual(median(data), 50.5)

    def test_median_large_odd_list(self):
        data = list(range(1, 102))
        self.assertEqual(median(data), 51)


if __name__ == '__main__':
    unittest.main()
